$short = static function (string $id, string $task, string $title, string $resource, string $prompt, array $answers, string $explanation, int $maxWords = 1, string $instructions = 'Write ONE WORD ONLY.'): array {
    return ['id' => $id, 'type' => 'short', 'task_type' => $task, 'title' => $title, 'resource_id' => $resource, 'prompt' => $prompt, 'instructions' => $instructions, 'max_words' => $maxWords, 'answer' => $answers, 'explanation' => $explanation];
};
$choice = static function (string $id, string $task, string $title, string $resource, string $prompt, array $options, string $answer, string $explanation, string $instructions = 'Choose ONE answer.'): array {
    $formatted = [];
    foreach ($options as $key => $text) {
        $formatted[] = ['id' => (string) $key, 'text' => $text];
    }
    return ['id' => $id, 'type' => 'choice', 'task_type' => $task, 'title' => $title, 'resource_id' => $resource, 'prompt' => $prompt, 'instructions' => $instructions, 'options' => $formatted, 'answer' => $answer, 'explanation' => $explanation];
};

